static int modern_deep_prefix_begin_r128(void*raw,uint64_t tx,size_t count,const int32_t*rows,const int32_t*past){try{
 auto*c=static_cast<Context*>(raw);if(!c||!count||count>c->cache->rows()||!rows||!past)throw std::invalid_argument("prefix begin metadata");std::vector<ProbeEngine::PrefixRowR128>q;
 for(size_t i=0;i<count;++i){if(rows[i]<0||past[i]<0)throw std::invalid_argument("prefix negative row/past");q.push_back({size_t(rows[i]),size_t(past[i]),2});}
 c->engine->prefix_begin_r128(tx,std::move(q),c->cache->rows());return 0;
}catch(const std::exception&e){error=e.what();return 1;}}
static int modern_deep_prefix_verify_r128(void*raw,size_t count,const int64_t*ids,const int64_t*positions,void*out_logits,void*out_ids){try{
 auto*c=static_cast<Context*>(raw);if(!c||!count||count>128||count!=c->engine->prefix_rows_r128.size()||!ids||!positions||!out_logits||!out_ids)throw std::invalid_argument("prefix verify metadata");
 std::vector<int32_t>rows,past,total,offsets;for(size_t i=0;i<count;++i){auto q=c->engine->prefix_rows_r128[i];rows.push_back(q.row);past.push_back(q.past);total.push_back(q.past+2);offsets.push_back(2*i);}offsets.push_back(2*count);
 en::InferEngine::Input input;input.input_ids=cpu(const_cast<int64_t*>(ids),{1,2*count},rt::DataType::kInt64);input.position_ids=cpu(const_cast<int64_t*>(positions),{1,2*count},rt::DataType::kInt64);input.past_sequence_lengths=cpu(past.data(),{count},rt::DataType::kInt32);input.total_sequence_lengths=cpu(total.data(),{count},rt::DataType::kInt32);input.input_offsets=cpu(offsets.data(),{count+1},rt::DataType::kInt32);input.mamba_init_state_indices=cpu(rows.data(),{count},rt::DataType::kInt32);input.mamba_final_state_indices=input.mamba_init_state_indices;input.sample_all_positions=true;input.top_k=1;input.top_p=1;input.temperature=1;
 auto out=c->engine->prefix_forward_r128(input);if(!out.logits||out.logits->numel()!=2*count*c->vocab||out.logits->dtype()!=rt::DataType::kBFloat16||!out.output_ids||out.output_ids->numel()!=2*count||out.output_ids->dtype()!=rt::DataType::kInt64)throw std::runtime_error("prefix actual all-position output differs");copy_cpu(out_logits,out.logits);copy_cpu(out_ids,out.output_ids);return 0;
}catch(const std::exception&e){error=e.what();return 1;}}
static int modern_deep_prefix_commit_r128(void*raw,size_t count,const uint64_t*accepted){try{
 auto*c=static_cast<Context*>(raw);if(!c||!accepted||count!=c->engine->prefix_rows_r128.size())throw std::invalid_argument("prefix commit count");std::vector<size_t>v;for(size_t i=0;i<count;++i)v.push_back(accepted[i]);c->engine->prefix_commit_r128(v);return 0;
}catch(const std::exception&e){error=e.what();return 1;}}
static int modern_deep_prefix_cancel_r128(void*raw){try{auto*c=static_cast<Context*>(raw);if(!c)throw std::invalid_argument("prefix null context");c->engine->prefix_cancel_r128();return 0;}catch(const std::exception&e){error=e.what();return 1;}}
extern "C" const char*modern_deep_prefix_status_r128(void*raw){try{auto*c=static_cast<Context*>(raw);if(!c)throw std::invalid_argument("prefix null context");auto&e=*c->engine;std::array<size_t,3>v{};if(e.prefix_group_r128)v=e.prefix_group_r128->counts();serialized=nlohmann::json{{"pending",bool(e.prefix_group_r128)},{"poisoned",e.prefix_poisoned_r128},{"generation",e.prefix_generation_r128},{"last_transaction",e.prefix_last_tx_r128},{"sealed_owners",v[0]},{"published_owners",v[1]},{"cancelled_owners",v[2]},{"fixed_cohort_only",true}}.dump();return serialized.c_str();}catch(const std::exception&e){error=e.what();return nullptr;}}

extern "C" const char*modern_deep_prefix_inspect_r129(void*raw,size_t count,const uint64_t*rows){try{auto*c=static_cast<Context*>(raw);if(!c||!count||count>128||!rows)throw std::invalid_argument("prefix inspect metadata");std::vector<size_t>v;for(size_t i=0;i<count;++i)v.push_back(rows[i]);serialized=c->engine->prefix_inspect_r129(v).dump();return serialized.c_str();}catch(const std::exception&e){error=e.what();return nullptr;}}
extern "C" int modern_deep_prefix_fault_r129(void*raw,int rank,int phase){try{auto*c=static_cast<Context*>(raw);const char*allowed=std::getenv("INFINILM_DEEP_PREFIX_FAULT_R129");if(!c||!allowed||std::strcmp(allowed,"1")||!c->engine->prefix_group_r128||c->engine->prefix_verified_r128)throw std::logic_error("prefix qualification fault disabled/state");c->engine->prefix_group_r128->configure_fault_r129(rank,phase);return 0;}catch(const std::exception&e){error=e.what();return 1;}}

static void prefix_ticket_check_r129(Context*c,uint64_t instance,uint64_t tx,uint64_t generation){if(!c||!c->engine->prefix_group_r128||instance!=c->prefix_instance_r129||tx!=c->engine->prefix_last_tx_r128||generation!=c->engine->prefix_generation_r128)throw std::invalid_argument("stale/foreign prefix ticket");}
extern "C" int modern_deep_prefix_begin_r129(void*raw,uint64_t tx,size_t n,const int32_t*rows,const int32_t*past){return modern_deep_prefix_begin_r128(raw,tx,n,rows,past);}
extern "C" const char*modern_deep_prefix_ticket_r129(void*raw){try{auto*c=static_cast<Context*>(raw);if(!c||!c->engine->prefix_group_r128)throw std::logic_error("prefix ticket without active transaction");serialized=nlohmann::json{{"instance",c->prefix_instance_r129},{"transaction",c->engine->prefix_last_tx_r128},{"generation",c->engine->prefix_generation_r128}}.dump();return serialized.c_str();}catch(const std::exception&e){error=e.what();return nullptr;}}
extern "C" int modern_deep_prefix_verify_r129(void*raw,uint64_t instance,uint64_t tx,uint64_t generation,size_t n,const int64_t*ids,const int64_t*positions,void*logits,void*outids){try{prefix_ticket_check_r129(static_cast<Context*>(raw),instance,tx,generation);return modern_deep_prefix_verify_r128(raw,n,ids,positions,logits,outids);}catch(const std::exception&e){error=e.what();return 1;}}
extern "C" int modern_deep_prefix_commit_r129(void*raw,uint64_t instance,uint64_t tx,uint64_t generation,size_t n,const uint64_t*accepted){try{prefix_ticket_check_r129(static_cast<Context*>(raw),instance,tx,generation);return modern_deep_prefix_commit_r128(raw,n,accepted);}catch(const std::exception&e){error=e.what();return 1;}}
extern "C" int modern_deep_prefix_cancel_r129(void*raw,uint64_t instance,uint64_t tx,uint64_t generation){try{prefix_ticket_check_r129(static_cast<Context*>(raw),instance,tx,generation);return modern_deep_prefix_cancel_r128(raw);}catch(const std::exception&e){error=e.what();return 1;}}
